@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD)
public @interface NotNull { String message() default "不能为空"; }

@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD)
public @interface Min { long value(); String message() default "不能小于最小值"; }

public static List<String> validate(Object target) {
    List<String> errors = new ArrayList<>();
    for (Field f : target.getClass().getDeclaredFields()) {
        f.setAccessible(true);
        try {
            Object v = f.get(target);
            NotNull nn = f.getAnnotation(NotNull.class);
            if (nn != null && v == null) errors.add(f.getName() + ": " + nn.message());
            Min min = f.getAnnotation(Min.class);
            if (min != null && v instanceof Number && ((Number) v).longValue() < min.value())
                errors.add(f.getName() + ": " + min.message());
        } catch (IllegalAccessException e) {
            throw new IllegalStateException("校验失败: " + f.getName(), e);
        }
    }
    return errors;
}

