public abstract class Animal {
    // 抽象方法：没有方法体，分号结尾
    public abstract void makeNoise();
    public abstract void eat();

    // 具体方法：有方法体，子类可直接继承
    public void sleep() {
        System.out.println("通用睡觉");
    }
    public void roam() {
        System.out.println("通用游荡");
    }
}

